#!/usr/bin/env node
// Generated by ajch_agent_framework 0.2.0. Edit the source named in .claude/kit.lock.json, then npm run kit.
/**
 * build-diagrams.mjs — render docs/diagrams/src/*.mjs to docs/diagrams/*.svg.
 * Shipped by ajch_agent_framework; rendered into each vertical as scripts/build-diagrams.mjs.
 *
 *   node scripts/build-diagrams.mjs                 write every SVG
 *   node scripts/build-diagrams.mjs --check         exit 1 if an SVG is missing or stale (CI)
 *   node scripts/build-diagrams.mjs --preview <dir> also write light and dark PNGs to <dir>
 *                                                   (needs Playwright; set PLAYWRIGHT_DIR to a
 *                                                   node_modules folder that has it)
 *   node scripts/build-diagrams.mjs <name>          only that diagram
 */
import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { join, dirname, resolve } from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import { createRequire } from 'module';

const ROOT = process.env.KIT_ROOT || join(dirname(fileURLToPath(import.meta.url)), '..');
const DIR = join(ROOT, 'docs', 'diagrams');
const SRC = join(DIR, 'src');
const args = process.argv.slice(2);
const check = args.includes('--check');
const quiet = args.includes('--quiet');
const pi = args.indexOf('--preview');
const preview = pi >= 0 ? resolve(args[pi + 1]) : null;
const only = args.filter((a, i) => !a.startsWith('--') && i !== pi + 1);

if (!existsSync(SRC)) { if (!quiet) console.log('diagrams: no docs/diagrams/src/'); process.exit(0); }
const names = readdirSync(SRC).filter((f) => f.endsWith('.mjs')).map((f) => f.replace(/\.mjs$/, '')).filter((n) => !only.length || only.includes(n));

const problems = [];
const built = [];
for (const name of names) {
  let svg;
  try {
    const mod = await import(pathToFileURL(join(SRC, `${name}.mjs`)).href + `?t=${Date.now()}`);
    svg = typeof mod.default === 'function' ? mod.default() : mod.default;
  } catch (e) { problems.push(`${name}: ${e.message}`); continue; }
  if (typeof svg !== 'string' || !svg.startsWith('<svg')) { problems.push(`${name}: default export must be diagram({...})`); continue; }
  const out = join(DIR, `${name}.svg`);
  const current = existsSync(out) ? readFileSync(out, 'utf-8').replace(/\r\n/g, '\n') : null;
  if (check) { if (current !== svg) problems.push(`${name}.svg is ${current === null ? 'missing' : 'stale'}: run npm run diagrams`); continue; }
  if (current !== svg) writeFileSync(out, svg);
  built.push({ name, svg });
}

if (preview && built.length) {
  const require = createRequire(join(resolve(process.env.PLAYWRIGHT_DIR || join(ROOT, 'node_modules')), 'x.js'));
  let chromium;
  try { ({ chromium } = require('playwright')); } catch { problems.push('preview: Playwright not found; set PLAYWRIGHT_DIR to a node_modules folder that has it'); }
  if (chromium) {
    mkdirSync(preview, { recursive: true });
    const browser = await chromium.launch();
    for (const scheme of ['light', 'dark']) {
      const page = await browser.newPage({ colorScheme: scheme, deviceScaleFactor: 1.5 });
      for (const { name, svg } of built) {
        const [, w, h] = svg.match(/width="(\d+(?:\.\d+)?)" height="(\d+(?:\.\d+)?)"/);
        await page.setViewportSize({ width: Math.ceil(+w) + 40, height: Math.ceil(+h) + 40 });
        await page.setContent(`<body style="margin:20px;background:${scheme === 'dark' ? '#0d1117' : '#ffffff'}"><img src="data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}"></body>`);
        await page.locator('img').screenshot({ path: join(preview, `${name}.${scheme}.png`) });
      }
      await page.close();
    }
    await browser.close();
  }
}

if (problems.length) { console.error(`diagrams: ${problems.length} problem(s)\n` + problems.map((p) => '  ' + p).join('\n')); process.exit(1); }
if (!quiet) console.log(`diagrams: ${names.length} ${check ? 'up to date' : 'built'}${preview ? `, previews in ${preview}` : ''}`);
